234	/// Check if the given annotation [`Expr`] explicitly allows `None`.
235	///
236	/// This function will return `None` if the annotation explicitly allows `None`
237	/// otherwise it will return the annotation itself. If it's a `Annotated` type,
238	/// then the inner type will be checked.
239	///
240	/// This function assumes that the annotation is a valid typing annotation expression.
241	pub(crate) fn type_hint_explicitly_allows_none<'a>(
242	    annotation: &'a Expr,
243	    checker: &'a Checker,
244	    version: ast::PythonVersion,
245	) -> Option<&'a Expr> {
246	    match TypingTarget::try_from_expr(annotation, checker, version) {
247	        None |
248	            // Short circuit on top level `None`, `Any` or `Optional`
249	            Some(TypingTarget::None | TypingTarget::Optional(_) | TypingTarget::Any) => None,
250	        // Top-level `Annotated` node should check for the inner type and
251	        // return the inner type if it doesn't allow `None`. If `Annotated`
252	        // is found nested inside another type, then the outer type should
253	        // be returned.
254	        Some(TypingTarget::Annotated(expr)) => {
255	            expr.and_then(|expr| type_hint_explicitly_allows_none(expr, checker, version))
256	        }
257	        Some(target) => {
258	            if target.contains_none(checker, version) {
259	                return None;
260	            }
261	            Some(annotation)
262	        }
263	    }
264	}
