9	/// Returns `true` if the given qualified name is a known type.
10	///
11	/// A known type is either a builtin type, any object from the standard library,
12	/// or a type from the `typing_extensions` module.
13	fn is_known_type(qualified_name: &QualifiedName, version: ast::PythonVersion) -> bool {
14	    match qualified_name.segments() {
15	        ["" | "typing_extensions", ..] => true,
16	        [module, ..] => is_known_standard_library(version.minor, module),
17	        _ => false,
18	    }
19	}
