75	fn parse_simple_type_annotation(
76	    string_literal: &StringLiteral,
77	    source: &str,
78	) -> AnnotationParseResult {
79	    Ok(ParsedAnnotation {
80	        parsed: parse_string_annotation(source, string_literal)?,
81	        kind: AnnotationKind::Simple,
82	    })
83	}
